-- Passage rg4-character-setting-plot-p02
insert into public.passages (id, code, skill_id, sat_alignment, grade_band, title, body, status)
values ('cc18cf7a-49bd-53e9-b2c4-880fc8069d95', 'rg4-character-setting-plot-p02', (select id from public.skills where slug = 'read-g4-character-setting-plot'), null,
        '3-5', $q$Snow Shovel Morning$q$, $q$The snow came down all night, soft and deep.
By morning, our whole street was white and still.
I wanted to build a fort before breakfast.
Then I saw Mrs. Kowalski at her window.

She is eighty-one and walks with a cane.
Her steps were buried, and so was her walk.
Her mail sat waiting in a box by the street.
She could not reach it without a path.

I grabbed my shovel, the small blue one.
My arms burned after the very first step.
My breath made clouds that floated away.
I scraped and lifted, scraped and lifted.

It took me most of an hour to finish.
My fort would have to wait until noon.
She opened the door with a smile and a mug.
"Hot cocoa," she said, "for my snow helper."

I sipped it slowly on her clean top step.
The fort could wait. This felt even better.$q$, 'draft')
