  ('2e84c7c0-4c14-5fa8-b4df-2148c5b8f3b6', null, (select id from public.skills where slug = 'read-g4-character-setting-plot'), null, 'hard',
   $q$What do Otter's actions in the story show about him?$q$, $q$[{"text":"He does not care what happens to the duckling.","is_correct":false,"misconception_token":"contradicts-text"},{"text":"He wants to help but acts before he thinks.","is_correct":true},{"text":"He is lazy and lets Turtle do all the work.","is_correct":false,"misconception_token":"opposite-trait"},{"text":"He is mostly trying to beat Turtle in a race.","is_correct":false,"misconception_token":"unsupported-inference"}]$q$::jsonb, $q$He wants to help but acts before he thinks.$q$, $q$Otter jumps in "at once" to help, but he "never stopped to look closely at anything," and his splashing scares the duckling. He is eager, not lazy or uncaring.$q$, 'draft', 'ee214064-ad1b-53eb-9f73-5d759cfbcfab')
