-- Passage rg4-character-setting-plot-p06
insert into public.passages (id, code, skill_id, sat_alignment, grade_band, title, body, status)
values ('19113831-523d-59e3-b689-f656474ca3a2', 'rg4-character-setting-plot-p06', (select id from public.skills where slug = 'read-g4-character-setting-plot'), null,
        '3-5', $q$The Borrowed Telescope$q$, $q$My cousin Amina lent me her telescope
for one clear night in late October.
The backyard was cold and very dark.
Even the porch light was switched off.

At first I saw only black and blur.
I almost carried it back inside.
"Be patient," Amina had told me.
"Your eyes need time to learn the dark."

So I sat on the step and waited.
I counted crickets. I counted breaths.
Slowly, one star turned into ten.
Then ten stars turned into a hundred.

I aimed the telescope at the moon.
It filled the circle, silver and close.
I saw craters like dents in a ball.
I saw shadows along the edges.

I stayed out until my fingers ached with cold.
Mom called me in three separate times.
Tomorrow I will write to Amina.
I will ask her how to find the planets.$q$, 'draft')
