-- Passage rg4-evidence-inference-p03
insert into public.passages (id, code, skill_id, sat_alignment, grade_band, title, body, status)
values ('aa38fc50-7a12-59c6-9a5d-aa9b1a234f2d', 'rg4-evidence-inference-p03', (select id from public.skills where slug = 'read-g4-evidence-inference'), null,
        '3-5', $q$A Sea Turtle Nest$q$, $q$On warm summer nights, a mother sea turtle crawls out of the ocean onto a sandy beach. She moves slowly because her flippers are made for swimming, not walking. Above the high tide line, she digs a deep hole with her back flippers. Then she lays about one hundred eggs, each about the size of a ping-pong ball.

When she is done, the mother covers the eggs with sand. She returns to the sea and does not come back for them. The warm sand keeps the eggs safe while the babies grow inside.

About two months later, the tiny turtles hatch. They usually dig out at night, when the sand is cooler. Then they scramble toward the water. The hatchlings find the sea by heading toward the brightest light. On a natural beach, that light is the moon and stars shining on the waves.

Bright lights from buildings can confuse the hatchlings and lead them the wrong way. For this reason, some beach towns ask people to turn off outdoor lights during nesting season. Volunteers also put small fences around nests so that no one steps on them.$q$, 'draft')
on conflict (id) do update set title = excluded.title, body = excluded.body
where public.passages.status = 'draft';
