insert into public.passages (id, code, skill_id, sat_alignment, grade_band, title, body, status)
values ('ee21fe15-be92-549a-b517-6f490b41ac70', 'rg4-evidence-inference-p06', (select id from public.skills where slug = 'read-g4-evidence-inference'), null,
        '3-5', $q$Making Paper by Hand$q$, $q$Ms. Okafor's art class learned to make new paper from old paper. First, the students tore scrap paper into small pieces. They soaked the pieces in a tub of warm water overnight. By morning, the paper was soft and mushy.

Next, a helper used a blender to turn the wet paper into a thick mix called pulp. The students poured the pulp into a big tub of water and stirred it. Then each student dipped a screen in a wooden frame into the tub. When they lifted it out, a thin layer of pulp lay on top of the screen.

The students pressed the pulp with a sponge to squeeze out water. They flipped the wet sheet onto a towel and peeled the screen away. Some students pressed flower petals or bits of colored thread into their sheets.

The sheets dried for two whole days. The finished paper was bumpy and thicker than notebook paper. Jamal said his sheet was perfect for a birthday card. Lucia noticed that her sheet had a light blue color, because she had used old blue paper.$q$, 'draft')
