  ('4432132e-8e18-54fd-b98c-f0893832321b', null, (select id from public.skills where slug = 'read-g4-literary-structure-pov'), null, 'medium',
   $q$How is this poem organized?$q$, $q$[{"text":"It is a list of questions that the bridge asks the children.","is_correct":false,"misconception_token":"contradicts-text"},{"text":"Each stanza tells about a different bridge in the town.","is_correct":false,"misconception_token":"unsupported-inference"},{"text":"It starts at night and moves backward to the early morning.","is_correct":false,"misconception_token":"reverses-sequence"},{"text":"It moves through the bridge's day, then ends with a big idea.","is_correct":true}]$q$::jsonb, $q$It moves through the bridge's day, then ends with a big idea.$q$, $q$The second and third stanzas move from morning to noon to evening, and the last stanza explains that the bridge helps everyone get home. The poem goes forward in time, not backward.$q$, 'draft', 'b8fb8ccc-8db6-59c5-8f03-eca7da2ef40b')
