  ('70981eb5-5b33-5800-9f4d-8d421b2ad614', null, (select id from public.skills where slug = 'read-g4-literary-structure-pov'), null, 'medium',
   $q$Suppose the line "I stretch across the creek" were changed to "The bridge stretches across the creek." How would the poem change?$q$, $q$[{"text":"The bridge would become a different kind of building.","is_correct":false,"misconception_token":"literal-reading"},{"text":"The poem would be in first person and spoken by a child.","is_correct":false,"misconception_token":"confuses-first-and-third-person"},{"text":"The poem would be in third person, not in the bridge's own voice.","is_correct":true},{"text":"The poem would turn into a drama with stage directions.","is_correct":false,"misconception_token":"confuses-pov-and-structure"}]$q$::jsonb, $q$The poem would be in third person, not in the bridge's own voice.$q$, $q$Using "The bridge" instead of "I" means someone outside is describing it, which is third person. In the poem as written, the bridge speaks for itself in first person.$q$, 'draft', 'b8fb8ccc-8db6-59c5-8f03-eca7da2ef40b')
