  ('1d2134f9-6247-50ba-ac19-60cf017865b8', null, (select id from public.skills where slug = 'read-g4-literary-structure-pov'), null, 'easy',
   $q$What does the first stage direction, "(Rain taps on the window...)," help the reader picture?$q$, $q$[{"text":"The rainy day and Juno getting ready behind the blanket","is_correct":true},{"text":"What Grandma Bea says when she first comes inside","is_correct":false,"misconception_token":"confuses-directions-with-dialogue"},{"text":"The words Marco will say when he lifts his puppet","is_correct":false,"misconception_token":"confuses-directions-with-dialogue"},{"text":"The ending, when Grandma Bea laughs at the show","is_correct":false,"misconception_token":"wrong-plot-stage"}]$q$::jsonb, $q$The rainy day and Juno getting ready behind the blanket$q$, $q$This stage direction describes the rain and shows Juno kneeling behind the blanket with puppets, so readers can picture the start of the scene. It does not include any spoken words.$q$, 'draft', 'd235f142-7dc9-5d1b-ae55-c893a4387c25')
