  ('56228469-c358-50a1-bacf-fac8ab222779', null, (select id from public.skills where slug = 'read-g4-literary-structure-pov'), null, 'medium',
   $q$How does the reader find out that Marco is unhappy with his puppet at first?$q$, $q$[{"text":"Juno tells Grandma Bea that Marco's puppet is ruined.","is_correct":false,"misconception_token":"contradicts-text"},{"text":"The direction \"(frowning)\" and his line about a potato show it.","is_correct":true},{"text":"A narrator says that Marco feels upset and wants to quit.","is_correct":false,"misconception_token":"confuses-prose-and-drama"},{"text":"Marco says so in a rhyming line at the end of a stanza.","is_correct":false,"misconception_token":"confuses-poetry-and-drama"}]$q$::jsonb, $q$The direction "(frowning)" and his line about a potato show it.$q$, $q$In a drama, feelings come through actions and words, and Marco is "(frowning at his paper bag puppet)" while saying it "looks more like a potato." There is no narrator in a play to tell us how he feels.$q$, 'draft', 'd235f142-7dc9-5d1b-ae55-c893a4387c25')
