  ('5d2caa31-cee7-533d-aef5-742523236604', null, (select id from public.skills where slug = 'read-g4-literary-structure-pov'), null, 'medium',
   $q$How is the structure of this drama different from the structure of a poem?$q$, $q$[{"text":"It uses a narrator, and a poem never has anyone speaking in it.","is_correct":false,"misconception_token":"confuses-prose-and-drama"},{"text":"It is written in stanzas, and a poem is written in paragraphs.","is_correct":false,"misconception_token":"confuses-poetry-and-drama"},{"text":"It is built from characters' lines and stage directions, not stanzas.","is_correct":true},{"text":"It has no characters, and a poem always has many characters.","is_correct":false,"misconception_token":"contradicts-text"}]$q$::jsonb, $q$It is built from characters' lines and stage directions, not stanzas.$q$, $q$A drama is written as lines for each character plus stage directions in parentheses, while a poem is usually written in lines grouped into stanzas. This play clearly has characters, so it is not missing them.$q$, 'draft', 'd235f142-7dc9-5d1b-ae55-c893a4387c25')
