  ('9d5de85c-ae0d-5476-b436-29075cfbb680', null, (select id from public.skills where slug = 'read-g4-literary-structure-pov'), null, 'easy',
   $q$Who tells Version One of the relay?$q$, $q$[{"text":"Keiko, the swimmer who touched the wall before Diego","is_correct":false,"misconception_token":"confuses-narrator-with-character"},{"text":"Diego's father, who watched from the stands","is_correct":false,"misconception_token":"confuses-narrator-with-character"},{"text":"Diego, the final swimmer, telling it in his own words","is_correct":true},{"text":"An outside narrator who calls Diego \"he\"","is_correct":false,"misconception_token":"confuses-first-and-third-person"}]$q$::jsonb, $q$Diego, the final swimmer, telling it in his own words$q$, $q$Version One uses "I" and "my," and the speaker is "the final swimmer," who is named Diego in Version Two. The outside narrator who calls him "he" tells Version Two, not Version One.$q$, 'draft', '1e39d97b-4fda-56b5-83a2-ff759e4bb067')
